import { PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh } = ctx.THREE;
  const mainGroup = new ThreeGroup();

  // 1. DIMENSIONS & GEOMETRY
  // Aspect ratio matching atlas region: 512 x 320 => 1.6
  const width = 2.4;
  const height = 1.5;
  const geometry = new PlaneGeometry(width, height);

  // 2. MATERIAL WITH PBR BACKING & STATIC GRADIENT
  // Premium dark-first color palette integration
  const inkColor = new Color(config?.intent?.visualSpec?.colors?.ink || '#16161d');
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.95,
  });

  const mesh = new ThreeMesh(geometry, material);
  mainGroup.add(mesh);

  // Subtle accent border backplate to give visual structure and depth
  const borderGeom = new PlaneGeometry(width + 0.04, height + 0.04);
  const borderMat = new MeshBasicNodeMaterial({
    color: config?.intent?.visualSpec?.colors?.accent || '#ff2a38',
    transparent: true,
    opacity: 0.3,
  });
  const borderMesh = new ThreeMesh(borderGeom, borderMat);
  borderMesh.position.z = -0.01;
  mainGroup.add(borderMesh);

  // 3. TEXTURE ATLAS MAP
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Atlas source rect: 0, 0, 512, 320
      // Safely calculate aspect settings once image resolves
      const imgWidth = tex.image ? tex.image.width : 512;
      const imgHeight = tex.image ? tex.image.height : 512;

      tex.repeat.set(512 / imgWidth, 320 / imgHeight);
      tex.offset.set(0, 1 - 320 / imgHeight);

      material.map = tex;
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed to load sprite texture for Collection Card 3:', err);
    });
  }

  // 4. CLEANUP DESTRUCTOR
  mainGroup.userData.cleanup = () => {
    geometry.dispose();
    borderGeom.dispose();
    material.dispose();
    borderMat.dispose();
  };

  return mainGroup;
}
